# ---------- patch name / locator syntax validation ----------
def patch_name_invalid_reason(name):
    if name=="": return "patch name may not be empty"
    if "/" in name: return "patch name may not contain '/'"
    if name.startswith("."): return "patch name may not start with '.'"
    if name.endswith(".lock"): return "patch name may not end with '.lock'"
    if name.endswith("."): return "patch name may not end with '.'"
    if ".." in name: return "patch name may not contain '..'"
    if name=="@": return "patch name may not be '@'"
    if name=="{base}": return "patch name may not be '{base}'"
    if "@{" in name: return "patch name may not contain '@{'"
    for ch,lab in [('~','~'),('^','^'),(':',' :'),('?','?'),('*','*'),('[','['),('\\','\\')]:
        if ch in name: return f"patch name may not contain '{ch}'"
    if any(c.isspace() for c in name): return "patch name may not contain whitespace"
    if any(ord(c)<32 or ord(c)==127 for c in name): return "patch name may not contain control characters"
    return None
def validate_patch_name_value(v):
    r=patch_name_invalid_reason(v)
    if r: raise ValueError(f"invalid patch name `{v}`: {r}")
    return v

def _unescape_dash(s):
    if s.startswith("\\-"): return s[1:]
    return s
def locator_syntax_ok(s):
    if s=="": return False
    if s.startswith("\\"):
        if not s.startswith("\\-"): return False
        return patch_name_invalid_reason(s[1:]) is None
    if ".." in s: return False
    if s.startswith("^"):
        rest=s[1:]
        if rest=="": return True
        if re.fullmatch(r'-?\d+([+~]\d*)*',rest): return True
        if re.fullmatch(r'([+~]\d*)+',rest): return True
        return False
    if "^" in s: return False
    if "~" in s:
        idx=s.find("~"); base=s[:idx]; suffix=s[idx:]
        if not re.fullmatch(r'([~+]\d*)+',suffix): return False
        if base in ("","@","{base}"): return True
        if re.fullmatch(r'\d+',base): return True
        if re.fullmatch(r'[+-]\d*',base): return True
        # base may be signed offset + suffix-ish e.g. -1, +1, or patch name possibly containing +
        return patch_name_invalid_reason(base) is None
    if s in ("@","{base}"): return True
    if s.startswith("{base}"):
        # +... forms are accepted syntactically as locator-ish
        return True
    return patch_name_invalid_reason(s) is None

