    if not locator_syntax_ok(v): raise ValueError(f"invalid patch locator `{v}`")
    return v
def validate_patch_range_value(v):
    if v=="": raise ValueError(f"invalid patch range `{v}`")
    # split on .. but note escaped? range endpoints individually may start \-
    parts=v.split("..")
    if len(parts)>2: raise ValueError(f"invalid patch range `{v}`")
    if len(parts)==2:
