def parse_patch_description_text(text):
    # Parse headers Patch:/Author:/Date: if present at top, strip comment lines (#) beyond scissors?
    # Returns dict with name/author/date/message/diff or None if not header format
    lines=text.replace("\r\n","\n").split("\n")
    name=None; author=None; date=None; idx=0; saw=False
    while idx<len(lines):
        ln=lines[idx]
        if ln.startswith("Patch:"):
            name=ln[len("Patch:"):].strip(); saw=True; idx+=1; continue
        if ln.startswith("Author:"):
            author=ln[len("Author:"):].strip(); saw=True; idx+=1; continue
        if ln.startswith("Date:"):
            date=ln[len("Date:"):].strip(); saw=True; idx+=1; continue
        break
    if not saw: return None
    # skip blank line(s)? Template has one blank line then message and comments
    body_lines=lines[idx:]
    # remove comment lines and scissors diff part
    msg_lines=[]; diff_lines=[]; in_diff=False
    for ln in body_lines:
        if ln.startswith("# ------------------------ >8 ------------------------"):
            in_diff=True; continue
        if in_diff:
            if ln.startswith("# "): continue
            if ln.startswith("#"): continue
            diff_lines.append(ln)
            continue
        if ln.startswith("#"):
            continue
        msg_lines.append(ln)
    # Remove leading blank line from template separator? cleanup will preserve one if multiple; header file from user maybe explicit blank.
    while msg_lines and msg_lines[0]=="":
        msg_lines=msg_lines[1:]
