            if rest=="" or re.fullmatch(r'([+~]\d*)+',rest or ""):
                idx=int(digits)
                if idx>=len(self.all): raise AppError(f"invalid patch index `{spec if rest=='' else digits}`")
                if rest: return self._apply_suffix(idx,rest,f"stack index `{digits}`")
                return idx
            # else fall through as name
        # @ + suffix
        if spec.startswith("@"):
            rest=spec[1:]
            if rest and re.fullmatch(r'([+~]\d*)+',rest):
                return self._apply_suffix(self.top_idx,rest,"topmost patch")
            self.patch_not_exist(spec)
        # bare ~...
        if spec.startswith("~"):
            m=re.match(r'^~(\d*)(.*)$',spec)
            if m:
                n=int(m.group(1)) if m.group(1) else 1; off=-n; rest=m.group(2)
                idx=self.top_idx+off
                if idx<0 or idx>=len(self.all):
                    raise AppError(f"no patch at `{off:+d}` from topmost patch" if off>=0 else f"no patch at `{off}` from topmost patch")
                if rest:
                    if not re.fullmatch(r'([+~]\d*)+',rest): self.patch_not_exist(spec)
                    off_disp=f"{off:+d}" if off>0 else str(off)
                    if off==0: off_disp="-0"
                    return self._apply_suffix(idx,rest,f"`{off_disp}` from topmost patch")
                return idx
        # bare signed offset single or with suffix
        if re.fullmatch(r'[+-]\d*',spec):
            sign=1 if spec[0]=='+' else -1; digits=spec[1:]; n=int(digits) if digits else 1; off=sign*n
            idx=self.top_idx+off
            if idx<0 or idx>=len(self.all):
                raise AppError(f"no patch at `{off:+d}` from topmost patch" if off>0 else f"no patch at `{off}` from topmost patch")
            return idx
        m=re.match(r'^([+-])(\d*)((?:[+~]\d*)+)$',spec)
        if m:
            sign=1 if m.group(1)=='+' else -1; n=int(m.group(2)) if m.group(2) else 1; off=sign*n; rest=m.group(3)
            idx=self.top_idx+off
            if idx<0 or idx>=len(self.all):
                raise AppError(f"no patch at `{off:+d}` from topmost patch" if off>0 else f"no patch at `{off}` from topmost patch")
            off_disp=f"{off:+d}" if off>0 else str(off)
            if off==0: off_disp="0"
            return self._apply_suffix(idx,rest,f"`{off_disp}` from topmost patch")
        # named base with ~ suffix
        if "~" in spec:
            idx0=spec.find("~"); base=spec[:idx0]; suffix=spec[idx0:]
            # base might itself be a locator like -1, 1, p1+1, @, {base}, ^
            if base=="": pass # handled above
            # resolve base recursively if base is not simply a name that does not exist (error should be base name)
            try:
                bidx=self.resolve(base)
            except AppError as e:
                # if base is plain name not exist, resolve() already raised patch `base`
                raise
            return self._apply_suffix(bidx,suffix,f"`{base}`" if base not in ("@","{base}") and not re.fullmatch(r'\d+',base or "") else ("topmost patch" if base=="@" else ("stack base" if base=="{base}" else f"stack index `{base}`")))
        # named base with + suffix (find existing patch prefix)
        # Prefer longest existing patch name that's a prefix followed by valid suffix
        candidates=[]
        for name in self.all:
            if spec.startswith(name) and len(spec)>len(name):
                suffix=spec[len(name):]
                if re.fullmatch(r'([+~]\d*)+',suffix): candidates.append((len(name),name,suffix))
        if candidates:
            candidates.sort(reverse=True); _,name,suffix=candidates[0]
            return self._apply_suffix(self.all.index(name),suffix,f"`{name}`")
        # plain name not exist
        self.patch_not_exist(spec)
    def resolve_name(self,spec):
        return self.all[self.resolve(spec)]
    def resolve_range(self,spec):
        if ".." not in spec:
            return [self.resolve_name(spec)]
        parts=spec.split("..")
        if len(parts)!=2: raise AppError(f"invalid patch range `{spec}`")
        a,b=parts
        if a=="" and b=="":
            if not self.all: return []
            begin=0
            end=self.top_idx if self.top_idx>=0 else len(self.all)-1
            # if begin is applied end top else last - begin 0 is applied iff top>=0
            return self.all[begin:end+1]
        if a=="":
            end=self.resolve(b); begin=0; return self.all[begin:end+1]
        begin=self.resolve(a)
        if b=="":
            end=self.top_idx if begin<=self.top_idx else len(self.all)-1
            return self.all[begin:end+1]
        end=self.resolve(b)
        if end<begin:
            raise AppError(f"end patch `{self.all[end]}` is out of order with `{self.all[begin]}`")
        return self.all[begin:end+1]

def resolve_patch_ranges(stack,specs,contiguous=False):
    r=LocatorResolver(stack); out_names=[]; intervals=[]
    for spec in specs:
        names=r.resolve_range(spec)
        intervals.append(names)
        for n in names:
            if n not in out_names: out_names.append(n)
    if contiguous and intervals:
        # each interval must be adjacent in stack order
        allp=stack.all_patches
        prev_end_idx=None; prev_spec=None
        combined=[]
        for spec,names in zip(specs,intervals):
            if not names: continue
            start=allp.index(names[0]); end=allp.index(names[-1])
            if prev_end_idx is not None and start!=prev_end_idx+1:
                raise AppError(f"`{names[0]}` not contiguous with preceding range `{prev_spec}`")
            combined.extend(names); prev_end_idx=end; prev_spec=spec
        return combined
    return out_names

# ---------- Patch edit / message ----------
def cleanup_message(msg):
    if msg is None: return ""
    # Normalize CRLF, strip trailing whitespace per line, remove leading/trailing blank lines but keep one leading blank if originally?
    msg=msg.replace("\r\n","\n").replace("\r","\n")
    lines=[ln.rstrip() for ln in msg.split("\n")]
    # StGit behaviour observed: "  \n\nmsg" -> "\nmsg\n", simple -> "simple\n", all spaces->""
    # It seems to strip leading/trailing empty lines somewhat like: trim trailing empty, then if message empty -> "". Leading: remove all but one? Let's reproduce observed:
    while lines and lines[-1]=="":
        lines.pop()
    if not lines: return ""
    # count leading empties
    lead=0
    while lead<len(lines) and lines[lead]=="": lead+=1
    if lead==len(lines): return ""
    if lead>0:
        lines=[""]+lines[lead:]
    return "\n".join(lines)+"\n"
def message_first_line(msg):
    for ln in msg.splitlines():
        return ln
    return ""
def generate_patch_name(message,existing):
    first=message_first_line(message or "")
    # Split into words: keep non-ASCII plus ASCII alnum . _ as word chars, others separators
    words=[]; cur=""
    s=first.lower()
    for ch in s:
        if ord(ch)>=128 or ch.isalnum() or ch in "._":
            cur+=ch
        else:
            if cur: words.append(cur); cur=""
    if cur: words.append(cur)
    # clean each word: collapse dots, strip leading/trailing dots
    cleaned=[]
    for w in words:
        w=re.sub(r'\.+','.',w).strip('.')
        if w.endswith('.lock'): w=w[:-5].strip('.')
        if w: cleaned.append(w)
    if not cleaned: base="patch"
    else:
        base=""
        for w in cleaned:
            cand=w if not base else base+"-"+w
            if len(cand)>30 and base:
                break
            base=cand
            if len(base)>30:
                # If first word long, keep whole
                break
        if not base: base="patch"
        # handle .lock at whole end
        if base.endswith('.lock'): base=base[:-5]
        base=base.strip('.')
        if not base: base="patch"
    if patch_name_invalid_reason(base):
        # fallback sanitize
        base="patch"
    name=base; n=1
    while name in existing:
        name=f"{base}-{n}"; n+=1
    return name

class PatchDesc:
    def __init__(self,name,author,authordate,message):
        self.name=name; self.author=author; self.authordate=authordate; self.message=message

def current_author_desc(repo,name,message,edit_opts,base_commit=None):
    # Determine author Sig and message after applying edit opts (not editor/file handled outside)
    # base author: from base_commit author if exists else git author ident
    if base_commit is not None:
        a=base_commit.author; author=Sig(a.name,a.email,a.ts,a.tz)
    else:
        ai=get_ident(repo,"AUTHOR")
        if ai is None:
            # will be caught when committing; use placeholder
            ai=Sig("","",int(datetime.datetime.now().timestamp()),"+0000")
        author=Sig(ai.name,ai.email,ai.ts,ai.tz)
    # apply opts if edit_opts present
    if edit_opts:
        au=edit_opts.get("author")
        if au:
            m=re.match(r'^(.*) <([^>]*)>$',au.strip())
            if m: author.name,author.email=m.group(1),m.group(2)
            else:
                # maybe just email/name? original errors handled elsewhere
                author.name=au
        if edit_opts.get("authname") is not None: author.name=edit_opts.get("authname")
        if edit_opts.get("authemail") is not None: author.email=edit_opts.get("authemail")
        if edit_opts.get("authdate"):
            ds=parse_date_input(repo,edit_opts.get("authdate")); author.ts,author.tz=ds.ts,ds.tz
    return PatchDesc(name,author,author,message)

def apply_trailers(message,edit_opts,repo):
    # signoff/ack/review lists may contain True (no value) or string
    if not edit_opts: return message
    additions=[]
    committer=get_ident(repo,"COMMITTER")
    default_val=str(committer) if committer else ""
    for key,label in [("signoff","Signed-off-by"),("ack","Acked-by"),("review","Reviewed-by")]:
        vals=edit_opts.get(key)
        if vals:
            if not isinstance(vals,list): vals=[vals]
            for v in vals:
                val=default_val if v is True else str(v)
                additions.append(f"{label}: {val}")
    if not additions: return message
    msg=cleanup_message(message)
    if msg and not msg.endswith("\n"): msg+="\n"
    # Ensure blank line before trailers if message has body and last paragraph isn't trailers? git interpret-trailers behaviour approximate:
    # For one-line message, original adds blank line then trailer (seen in show: "x\n    \n    Signed-off-by: foo")
    if msg.strip()=="":
        return "\n".join(additions)+"\n"
    lines=msg.rstrip("\n").split("\n")
    # check last paragraph is trailer-like
    # Use git interpret-trailers if available
    try:
        inp=msg
        args=["interpret-trailers"]
        for a in additions: args+=["--trailer",a]
        p=git_out(*args,inp=inp)
        if p.returncode==0:
            return cleanup_message(p.stdout.decode('utf-8','surrogateescape'))
    except Exception: pass
    return msg.rstrip("\n")+"\n\n"+"\n".join(additions)+"\n"

def parse_patch_description_text(text):
    # Parse headers Patch:/Author:/Date: if present at top, strip comment lines (#) beyond scissors?
    # Returns dict with name/author/date/message/diff or None if not header format
    lines=text.replace("\r\n","\n").split("\n")
    name=None; author=None; date=None; idx=0; saw=False
    while idx<len(lines):
        ln=lines[idx]
        if ln.startswith("Patch:"):
            name=ln[len("Patch:"):].strip(); saw=True; idx+=1; continue
        if ln.startswith("Author:"):
            author=ln[len("Author:"):].strip(); saw=True; idx+=1; continue
        if ln.startswith("Date:"):
            date=ln[len("Date:"):].strip(); saw=True; idx+=1; continue
        break
    if not saw: return None
    # skip blank line(s)? Template has one blank line then message and comments
    body_lines=lines[idx:]
    # remove comment lines and scissors diff part
    msg_lines=[]; diff_lines=[]; in_diff=False
    for ln in body_lines:
        if ln.startswith("# ------------------------ >8 ------------------------"):
            in_diff=True; continue
        if in_diff:
            if ln.startswith("# "): continue
            if ln.startswith("#"): continue
            diff_lines.append(ln)
            continue
        if ln.startswith("#"):
            continue
        msg_lines.append(ln)
    # Remove leading blank line from template separator? cleanup will preserve one if multiple; header file from user maybe explicit blank.
    while msg_lines and msg_lines[0]=="":
        msg_lines=msg_lines[1:]
        break
    message="\n".join(msg_lines)
    return {"name":name,"author":author,"date":date,"message":message,"diff":"\n".join(diff_lines) if diff_lines else None}

def make_template(desc_name,author_sig,message,diff_text=None,include_diff=False):
    s=f"Patch:  {desc_name or ''}\nAuthor: {author_sig.name} <{author_sig.email}>\nDate:   {author_sig.date_str()}\n\n"
    msg=cleanup_message(message) if message else ""
    s+=msg
    if msg and not msg.endswith("\n"): s+="\n"
    if msg: s+="\n"
    else: s+="\n"
    s+="# Please enter the message for your patch. Lines starting with\n# '#' will be ignored. An empty message aborts the new patch.\n# The patch name and author information may also be modified.\n"
    if include_diff:
        s+="# The diff below may be edited.\n# ------------------------ >8 ------------------------\n# Do not modify or remove the line above.\n"
        if diff_text: s+=diff_text
    return s

def run_editor(repo,initial_text,filename_hint=".stgit-edit.txt"):
    # Determine editor: GIT_EDITOR, core.editor, VISUAL, EDITOR, vi (in git order: GIT_EDITOR, core.editor, VISUAL, EDITOR)
    editor=os.environ.get("GIT_EDITOR") or repo.config_get("core.editor") or os.environ.get("VISUAL") or os.environ.get("EDITOR") or "vi"
    # file at repo worktree root? observed .stgit-edit.txt in cwd (/workspace) which was root. Use cwd?
    path=os.path.join(os.getcwd(),filename_hint)
    Path(path).write_text(initial_text,encoding='utf-8',errors='surrogateescape')
    err_out("hint: Waiting for your editor to close the file...\n")
    try:
        # editor is shell command; git uses sh -c "$editor \"$@\"" 
        p=subprocess.run(editor+f' "{path}"',shell=True)
    except Exception as e:
        raise AppError(f"running editor: {editor}: {e}")
    if p.returncode!=0:
        # Determine if editor not found: shell returns 127 etc. Original: "running editor: vi: No such file or directory (os error 2)"
        # Check existence of first word
        first=shlex.split(editor)[0] if editor else editor
        if not any(os.path.isfile(os.path.join(d,first)) and os.access(os.path.join(d,first),os.X_OK) for d in os.environ.get("PATH","").split(os.pathsep)) and not os.path.isfile(first):
            raise AppError(f"running editor: {editor}: No such file or directory (os error 2)")
        raise AppError(f"running editor: {editor}: exited with status {p.returncode}")
    try:
        content=Path(path).read_text(encoding='utf-8',errors='surrogateescape')
    finally:
        try: os.unlink(path)
        except OSError: pass
    return content

def get_patch_desc_from_opts(repo,opts,default_name,default_message,base_commit=None,default_author_commit=None,allow_editor=True,diff_text=None,template_message=""):
    # opts may include file/message/edit/diff/save_template etc. Returns PatchDesc or handles save_template exit
    # Determine base desc
    name=default_name
    if default_author_commit is not None: base_c=default_author_commit
    else: base_c=base_commit
    desc=current_author_desc(repo,name,default_message,None,base_commit=base_c)
    # if file/message/edit sources
    source_text=None; from_file=False
    if opts and opts.get("file"):
        f=opts.get("file"); from_file=True
        if f=="-": source_text=sys.stdin.buffer.read().decode('utf-8','surrogateescape')
        else:
            try: source_text=Path(f).read_text(encoding='utf-8',errors='surrogateescape')
            except FileNotFoundError: raise AppError(f"could not open `{f}`: No such file or directory (os error 2)")
            except OSError as e: raise AppError(str(e))
    elif opts and opts.get("message") is not None:
        desc.message=opts.get("message")
    if source_text is not None:
        parsed=parse_patch_description_text(source_text)
        if parsed:
            if parsed["name"]: desc.name=parsed["name"]
            if parsed["author"]:
                m=re.match(r'^(.*) <([^>]*)>$',parsed["author"].strip())
                if m: desc.author.name,desc.author.email=m.group(1),m.group(2)
            if parsed["date"]:
                ds=parse_date_input(repo,parsed["date"]); desc.author.ts,desc.author.tz=ds.ts,ds.tz
            desc.message=parsed["message"]
            desc.diff=parsed.get("diff")
        else:
            desc.message=source_text
            desc.diff=None
    else:
        desc.diff=None
    # apply explicit author opts (override file?)
    desc2=current_author_desc(repo,desc.name,desc.message,opts,base_commit=None)
    # current_author_desc with base None would reset author to git author; instead manually apply:
    # Use desc.author as base and apply opts fields
    author=desc.author
    if opts:
        if opts.get("author"):
            m=re.match(r'^(.*) <([^>]*)>$',opts.get("author").strip())
            if m: author.name,author.email=m.group(1),m.group(2)
        if opts.get("authname") is not None: author.name=opts.get("authname")
        if opts.get("authemail") is not None: author.email=opts.get("authemail")
        if opts.get("authdate"):
            ds=parse_date_input(repo,opts.get("authdate")); author.ts,author.tz=ds.ts,ds.tz
    desc.author=author
    # save template before editor/message application? If --save-template, write desc (?) with opts applied and message as default/from? Original for new --save-template with no -m: empty message.
    if opts and opts.get("save_template"):
        tmpl=make_template(desc.name or "",desc.author,desc.message or "",diff_text=diff_text,include_diff=bool(opts.get("diff")))
        dest=opts.get("save_template")
        if dest=="-": out(tmpl)
        else: Path(dest).write_text(tmpl,encoding='utf-8',errors='surrogateescape')
        raise SystemExit(0)
    # editor if needed
    need_editor=False
    if allow_editor:
        if opts and opts.get("edit"): need_editor=True
        elif not (opts and (opts.get("message") is not None or opts.get("file"))):
            # caller decides default need via allow_editor flag and a marker in opts '_editor_by_default'
            if opts and opts.get("_editor_by_default"): need_editor=True
    if need_editor:
        tmpl=make_template(desc.name or "",desc.author,desc.message or "",diff_text=diff_text,include_diff=bool(opts and opts.get("diff")))
        edited=run_editor(repo,tmpl)
        parsed=parse_patch_description_text(edited)
        if parsed:
            if parsed["name"] is not None: desc.name=parsed["name"]
            if parsed["author"]:
                m=re.match(r'^(.*) <([^>]*)>$',parsed["author"].strip())
                if m: desc.author.name,desc.author.email=m.group(1),m.group(2)
            if parsed["date"]:
                ds=parse_date_input(repo,parsed["date"]); desc.author.ts,desc.author.tz=ds.ts,ds.tz
            desc.message=parsed["message"]; desc.diff=parsed.get("diff")
        else:
            desc.message=edited
    desc.message=cleanup_message(desc.message or "")
    desc.message=apply_trailers(desc.message,opts,repo) if opts else desc.message
    return desc

# ---------- Transaction ----------
class Transaction:
    def __init__(self,stack,log_msg,allow_conflicts=True,committer_date_is_author_date=False):
        self.repo=stack.repo; self.orig_stack=stack; self.stack=stack.clone_state()
        self.log_msg=log_msg; self.allow_conflicts=allow_conflicts; self.committer_date_is_author_date=committer_date_is_author_date
        self.events=[]; self.conflict=None; self.worktree_mode="checkout"; self.print_top=True
        self.old_head=stack.head
        self.conflict_patch=None
    # event helpers
    def ev(self,line): self.events.append(line)
    def event_pop(self,names):
        if not names: return
        if len(names)==1: self.ev(f"- {names[0]}")
        else: self.ev(f"- {names[0]}..{names[-1]}")
    def event_push_single(self,name,suffix=None):
        # suffix computed later? determine empty at call time
        suf=""
        if suffix: suf=f" ({suffix})"
        elif name in self.stack.patches:
            try:
                if Commit(self.repo,self.stack.patches[name]).is_empty(): suf=" (empty)"
            except Exception: pass
        self.ev(f"> {name}{suf}")
    def pop_patches_internal(self,names,record=True):
        # names: subset of applied in stack order, must be suffix contiguous from some point to top (caller ensures)
        # Remove from applied, prepend to unapplied in order
        names_ordered=[n for n in self.stack.applied if n in names]
        # compute new head: parent of first popped
        if names_ordered:
            first_c=Commit(self.repo,self.stack.patches[names_ordered[0]])
            new_head=first_c.parents[0] if first_c.parents else first_c.oid
        else: new_head=self.stack.head
        self.stack.applied=[n for n in self.stack.applied if n not in names]
        self.stack.unapplied=names_ordered+[n for n in self.stack.unapplied if n not in names]
        self.stack.head=new_head
        if record: self.event_pop(names_ordered)
        return names_ordered
    def push_one_internal(self,name,set_tree=False,merged=False,record_prefix=None,suffix_force=None):
        # returns True success, False conflict stopped
        patch_oid=self.stack.patches[name]
        pc=Commit(self.repo,patch_oid)
        curr_head=self.stack.head; curr_c=Commit(self.repo,curr_head)
        new_oid=patch_oid; is_empty=False
        if set_tree:
            if not (pc.parents and pc.parents[0]==curr_head):
                new_oid=create_commit(self.repo,pc.tree,[curr_head],pc.message,author=pc.author,committer_date=(pc.author if self.committer_date_is_author_date else None))
            # empty if tree same as curr
            is_empty=(pc.tree==curr_c.tree)
        elif pc.parents and pc.parents[0]==curr_head:
            new_oid=patch_oid; is_empty=pc.is_empty()
        else:
            base_tree=Commit(self.repo,pc.parents[0]).tree if pc.parents else "4b825dc642cb6eb9a060e54bf8d69288fbee4904"
            result,conflicts=merge_trees(self.repo,base_tree,curr_c.tree,pc.tree)
            if conflicts:
                if not self.allow_conflicts:
                    raise _DisallowConflict(name)
                # placeholder commit
                new_oid=create_commit(self.repo,curr_c.tree,[curr_head],pc.message,author=pc.author,committer_date=(pc.author if self.committer_date_is_author_date else None))
                self.stack.patches[name]=new_oid
                # move to applied
                self.stack.unapplied=[n for n in self.stack.unapplied if n!=name]
                self.stack.hidden=[n for n in self.stack.hidden if n!=name]
                self.stack.applied.append(name); self.stack.head=new_oid
                self.conflict=(result,conflicts,curr_c.tree); self.conflict_patch=name
                # event with record_prefix
                prefix=record_prefix if record_prefix else ">"
                self.ev(f"{prefix} {name} (conflict)")
                return False
            merged_tree=tree_from_map(self.repo,result)
            # merged upstream check if requested is handled by caller outside?
            new_oid=create_commit(self.repo,merged_tree,[curr_head],pc.message,author=pc.author,committer_date=(pc.author if self.committer_date_is_author_date else None))
            is_empty=(merged_tree==curr_c.tree)
        self.stack.patches[name]=new_oid
        self.stack.unapplied=[n for n in self.stack.unapplied if n!=name]
        self.stack.hidden=[n for n in self.stack.hidden if n!=name]
        if name not in self.stack.applied: self.stack.applied.append(name)
        self.stack.head=new_oid
        # event
        prefix=record_prefix if record_prefix else ">"
        suf=""
        if suffix_force: suf=f" ({suffix_force})"
        elif is_empty: suf=" (empty)"
        self.ev(f"{prefix} {name}{suf}")
        return True
    def commit(self,log_msg=None):
        msg=log_msg if log_msg is not None else self.log_msg
        if self.conflict: msg=msg+" (CONFLICT)" if not msg.endswith(" (CONFLICT)") else msg
        # worktree handling for current branch
