def rev_resolve(repo,stack,rev):
    # returns commit oid
    if rev is None:
        return stack.head if stack else repo.head_oid()
    if rev=="":
        raise AppError("patch `` does not exist")
    # branch:rest
    if ":" in rev:
        branch,rest=rev.split(":",1)
        if branch and rest:
            # If rest looks like a path in a git tree-ish AND branch is not a branch? StGit treats as branch:patch
            # But git revisions such as HEAD:file - branch HEAD not found per observed master:HEAD? (it treated HEAD as patch in master)
            other=Stack.open(repo,branch,require_initialized=False)
            return rev_resolve(repo,other,rest)
    if rev=="{base}":
        return stack.base_oid()
    # split git suffix at first ^ (not index0) or @{
    split_idx=None; split_kind=None
    # find @{
    ai=rev.find("@{")
    ci=rev.find("^",1)
    cands=[]
    if ai>0: cands.append(ai)
    if ci>0: cands.append(ci)
    if cands:
        split_idx=min(cands); base_str=rev[:split_idx]; suffix=rev[split_idx:]
        # try base as patch/stgit first if base_str is patch locator or {base}; else let git handle whole
        base_oid=None
        if base_str=="{base}": base_oid=stack.base_oid()
        else:
            try:
                base_oid=stack.patches[LocatorResolver(stack).resolve_name(base_str)]
            except Exception:
                base_oid=None
        if base_oid:
            # apply suffix via git rev-parse
            combined=base_oid+suffix
            p=git_out("rev-parse","-q","--verify",combined+"^{commit}")
            if p.returncode==0: return p.stdout.decode().strip()
            # special errors for root ^ and @{
            if suffix.startswith("@{"):
                raise AppError(f'invalid StGit revision `{combined}`: Reflog entries require a ref name, got "{base_oid}"')
            if suffix.startswith("^"):
                # determine parent number
                # parse first ^ / ^N /^ etc approximate
                c=Commit(repo,base_oid)
                # count parents for message - use first parent request 1
                short=base_oid[:7]
                raise AppError(f"invalid StGit revision `{combined}`: Commit {short} has {len(c.parents)} parents and parent number 1 is out of range")
            raise AppError(f"invalid StGit revision `{combined}`")
        # git whole
        oid=repo.rev_parse(rev)
        if oid: return oid
        # fall through to patch error on base_str
        raise AppError(f"patch `{base_str}` does not exist"+format_similar(base_str,stack.all_patches))
    # try patch locator
    try:
        name=LocatorResolver(stack).resolve_name(rev)
        return stack.patches[name]
    except AppError as patch_err:
        # Try git revision
        oid=repo.rev_parse(rev)
        if oid: return oid
