def read_series_file(path):
    try: txt=Path(path).read_text(encoding='utf-8',errors='surrogateescape')
    except FileNotFoundError: raise AppError("No such file or directory (os error 2)")
    except OSError as e: raise AppError(f"{e.strerror} (os error {e.errno})")
    names=[]
    for line in txt.splitlines():
        # Series format: ignore blank/comments; patch name is first field, strip trailing comment?
        s=line.strip()
        if not s or s.startswith("#"): continue
        # If line has options after whitespace, original may take whole? Use first token
