def delete_patches_internal(repo,st,names,spill=False,branch_stack=False,log_msg="delete",allow_conflicts=True):
    # names in stack order preferred by caller
    if not names: return 0
    # Order names by all_patches order for applied segment logic, but event # order may be ?? Use stack order for now
    allp=st.all_patches; names_sorted=sorted(names,key=lambda n: allp.index(n) if n in allp else 0)
    is_cur=st.is_current()
    if is_cur and not branch_stack:
        st.check_head()
        if any(n in st.applied for n in names_sorted) and not spill: check_clean(repo)
        elif any(n in st.applied for n in names_sorted): check_no_conflicts(repo)
    trans=Transaction(st,log_msg,allow_conflicts=allow_conflicts)
    applied_selected=[n for n in names_sorted if n in st.applied]
    if applied_selected:
        min_idx=min(st.applied.index(n) for n in applied_selected); segment=st.applied[min_idx:]
        repush=[n for n in segment if n not in names_sorted]
        trans.pop_patches_internal(segment,record=True)
        # delete all selected patches (applied now unapplied + unapplied/hidden)
        for n in names_sorted:
            trans.stack.applied=[x for x in trans.stack.applied if x!=n]
            trans.stack.unapplied=[x for x in trans.stack.unapplied if x!=n]
            trans.stack.hidden=[x for x in trans.stack.hidden if x!=n]
            trans.stack.patches.pop(n,None); trans.ev(f"# {n}")
        for idx,n in enumerate(repush):
            prefix=">" if idx==len(repush)-1 else "+"
            try: ok=trans.push_one_internal(n,record_prefix=prefix)
            except _DisallowConflict as e: raise AppError(f"pushing patch `{e.patch}` would result in conflicts and push conflicts are disallowed",code=3)
            if not ok: break
    else:
        for n in names_sorted:
            trans.stack.unapplied=[x for x in trans.stack.unapplied if x!=n]
            trans.stack.hidden=[x for x in trans.stack.hidden if x!=n]
            trans.stack.patches.pop(n,None); trans.ev(f"# {n}")
    trans.worktree_mode="none" if (spill or not is_cur) else "checkout"
    trans.commit(log_msg); return 0

