        for n in names_sorted:
            trans.stack.applied=[x for x in trans.stack.applied if x!=n]
            trans.stack.unapplied=[x for x in trans.stack.unapplied if x!=n]
            trans.stack.hidden=[x for x in trans.stack.hidden if x!=n]
            trans.stack.patches.pop(n,None); trans.ev(f"# {n}")
