def effective_timeline(repo,st):
    chain=simplified_chain(repo,st)  # newest->oldest
    timeline=[]; ptr=-1
    for c in reversed(chain):
        p=git_out("cat-file","-p",f"{c.oid}:stack.json"); 
        if p.returncode!=0: continue
        data=json.loads(p.stdout.decode())
        msg=c.message.splitlines()[0] if c.message.splitlines() else ""
        mu=re.match(r'^undo (\d+)$',msg); mr=re.match(r'^redo (\d+)$',msg)
        if mu: ptr-=int(mu.group(1))
